package dev.zomboid.mts;
public final class EngineResponse {
 public static double rise(double maxRPM,double torque,double engineMass,double vehicleMass,double gear){double inertia=Math.sqrt(Math.max(1,engineMass)/180);double load=gear==0?1:Math.sqrt(Math.max(300,vehicleMass)/1200)/Math.sqrt(Math.max(.3,Math.abs(gear)));double seconds=Math.max(2.5,Math.min(7,3.5*inertia*load/Math.sqrt(Math.max(.1,torque))));return Math.max(20,maxRPM/seconds/20);}
 public static double limit(double requested,Object engine){Object v=R.get(engine,"vehicleOn");if(v==null||!Mechanics.car(v)||!R.yes(R.get(engine,"running")))return requested;double before=R.num(R.get(engine,"rpm"));if(requested<=before)return requested;Object d=R.get(R.get(engine,"definition"),"engine");double torque=R.num(R.get(d,"fuelConsumption"))+R.num(R.get(d,"superchargerFuelConsumption"))*R.num(R.get(d,"superchargerEfficiency"));double mass=R.num(R.get(R.get(R.get(engine,"definition"),"generic"),"mass"));if(mass<=0)mass=100+torque*100;double gear=R.num(R.get(R.get(engine,"gearRatioVar"),"currentValue"));return Math.min(requested,before+rise(R.num(R.get(d,"maxRPM")),torque,mass,R.num(R.get(v,"currentMass")),gear));}
}
